KG42.register("nodes-d3b1fdff1bec09f8ed153658",{"id":"COMP-8c75001a94cd69f5","code":"CLR044","label":"Loss-consistency conditions and dynamic purchase-price rules for community bilateral exchange","definition":"The primary definition is the feasible relationship for bilaterally transacted electricity quantities: each household's total sales and total purchases respectively aggregate the pairwise flows, I^{p}(t,h←p)=ψ^{P2P}X^{p}(t,p→h), and total sales after community-loss adjustment equal total purchases; it also contains an execution rule that applies each household's dynamic purchase price to P2P exchange.","layer":"L5","template_code":"BCT","concept_id":"execution.energy_trade","concept_ids":["execution.energy_trade"],"identity_dimensions":{"identity_fields":["Object: directed bilateral buy and sell electricity quantities within the community, and the application of the transaction purchase price","Core relationship 1: aggregation of pairwise flows, loss conversion between the reverse buy and sell directions, and consistency of community totals","Core relationship 2: the dynamic local purchase price is applied to the P2P exchange of the corresponding house","Output: the feasible traded-electricity-quantity relationship and the price-application relationship"]},"exclusions":["The house and the peer must be different, indexed by the model time period","ψ^{P2P} denotes distribution losses and distributed-generation conversion","Transactions are limited to within the community; grid feed-in is not allowed","Selling local renewable surplus electricity to peers is allowed"],"members":[{"id":"26-battery_flexibility::v141-c-R002::V::execution.energy_trade","rule_id":"v141-c-R002","market_meaning":"The dynamic local P2P price is applied as each house's purchase price for P2P exchanges. Scope: Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. Peers may sell excess electricity from locally generated renewable energy to other peers within the community. Scope: Flexi User peer exchanges within the community. P2P sales and purchases remain within the community under the design's exclusion of grid feed-in. Scope: Flexi User P2P sales and purchases. Each house's total P2P sales and purchases aggregate bilateral flows with other peers. Bilateral purchases equal the corresponding reverse-direction sales adjusted by the distribution-loss and DG-conversion factor; total community purchases must likewise equal adjusted community sales. Scope: Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. | Flexi User P2P sales and purchases. | Flexi User peer exchanges within the community. | Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e18","v141-b-g02-e16"]},"constraint_refs":["26-battery_flexibility::v141-c-R002::v141-c-R002-C001","26-battery_flexibility::v141-c-R002::v141-c-R002-C002","26-battery_flexibility::v141-c-R002::v141-c-R002-C003","26-battery_flexibility::v141-c-R002::v141-c-R002-C004"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"f5f3489e0aeb1a9f8ab702d6f918da1e040043dfec31bf1372cea634f8ce8089","paper":"26-battery_flexibility","rule_ref":"26-battery_flexibility::v141-c-R002","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"26-battery_flexibility::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":true},{"id":"26-battery_flexibility::v141-c-R007::V::execution.energy_trade","rule_id":"v141-c-R007","market_meaning":"The purchasing prosumer incurs a cost and the selling peer earns money when the P2P transaction occurs. Scope: Flexi User community P2P purchases by prosumers and corresponding seller receipts. Condition: A prosumer buys electricity from a fellow peer.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Flexi User community P2P purchases by prosumers and corresponding seller receipts.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e19"]},"constraint_refs":["26-battery_flexibility::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"b47cf85a1db97d6ba071d95e51f754d7c00025391b4f040009b2cde76846e99d","paper":"26-battery_flexibility","rule_ref":"26-battery_flexibility::v141-c-R007","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"26-battery_flexibility::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["26-battery_flexibility"],"evidence":[{"evidence_id":"v141-b-g01-e01","location":{"location_id":"src-9788b5496d-p04-c2r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"he ability to sell excess electricity from renewable energy sources to peers. Each of the two setups","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Decentralised storage – Flexi User Market: This market design applies rules to the system setup with individually owned batteries. Prosumers and consumers within a community can trade locally produced energy at a dynamic local P2P price. Privately owned storage can be charged by DG from prosumers within the community.","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"Decentralised storage – Flexi User Market: This market design applies rules to the system setup with individually owned batteries. Prosumers and consumers within a community can trade locally produced energy at a dynamic local P2P price. Privately owned storage can be charged by DG from prosumers within the community."},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-9788b5496d-p07-c1r3__v141-a-M01-pricing","page":7,"printed_page":null,"section":"4.1.4 Electricity prices","anchor_text":"Fig. 3. Demand cover for exemplary houses on a scaled up to represent typical price levels customers","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"A reasonable price for P2P trade should reflect the willingness of each prosumer to pay for an extra unit of electricity under the assumption that there is no possibility for local trade or storage. The shadow price of each single prosumer can be seen as the willingness to pay of each prosumer. This approach is analogous to the proposition of Abbaspourtorbati et al. [45] who calculated clearing prices by the dual variables of the energy balance equations. To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step. Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade.","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"A reasonable price for P2P trade should reflect the willingness of each prosumer to pay for an extra unit of electricity under the assumption that there is no possibility for local trade or storage. The shadow price of each single prosumer can be seen as the willingness to pay of each prosumer. This approach is analogous to the proposition of Abbaspourtorbati et al. [45] who calculated clearing prices by the dual variables of the energy balance equations. To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step. Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."},{"evidence_id":"v141-b-g01-e06","location":{"location_id":"src-9788b5496d-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"Table 1","anchor_text":"dem(t , h ) Demand of house h in time step t res (t , h ) Renewable energy production of house h in ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Table 1. Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T — Hours t in time horizon T; h, p ∈ H — Houses h and peers p in community H. Scalars: \\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale; \\underline{s}/\\bar{s} — Upper/lower bounds of storage level in battery; \\alpha/\\beta — Maximum charge/discharge rate of battery; \\eta^c/\\eta^d — Battery charging/discharging efficiency. Parameters: dem^{(t,h)} — Demand of house h in time step t; res^{(t,h)} — Renewable energy production of house h in time step t; p_G^{(t)} — Price of electricity from the grid in time step t; p_{p2p}^{(t,h)} — Price of electricity in the local market for house h in time step t; p_C^{(t)} — Price of charging the common battery in time step t; p_D^{(t,h)} — Price of discharging the common battery in time step t. Variables: C^{(t,h)} — Charge of battery of house h in time step t; D^{(t,h)} — Discharge of battery of house h in time step t; G^{(t,h)} — Grid consumption of house h in time step t; I^{(t,h)} — P2P electricity purchase of house h in time step t; I^{p}(t,h\\leftarrow p) — P2P electricity purchase of house h from peer p in time step t; S^{(t,h)} — Energy storage level in battery of house h in time step t; X^{(t,h)} — P2P electricity sale of house h in time step t; X^{p}(t,h\\rightarrow p) — P2P electricity sale of house h to peer p in time step t.","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"Table 1. Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T — Hours t in time horizon T; h, p ∈ H — Houses h and peers p in community H. Scalars: \\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale; \\underline{s}/\\bar{s} — Upper/lower bounds of storage level in battery; \\alpha/\\beta — Maximum charge/discharge rate of battery; \\eta^c/\\eta^d — Battery charging/discharging efficiency. Parameters: dem^{(t,h)} — Demand of house h in time step t; res^{(t,h)} — Renewable energy production of house h in time step t; p_G^{(t)} — Price of electricity from the grid in time step t; p_{p2p}^{(t,h)} — Price of electricity in the local market for house h in time step t; p_C^{(t)} — Price of charging the common battery in time step t; p_D^{(t,h)} — Price of discharging the common battery in time step t. Variables: C^{(t,h)} — Charge of battery of house h in time step t; D^{(t,h)} — Discharge of battery of house h in time step t; G^{(t,h)} — Grid consumption of house h in time step t; I^{(t,h)} — P2P electricity purchase of house h in time step t; I^{p}(t,h\\leftarrow p) — P2P electricity purchase of house h from peer p in time step t; S^{(t,h)} — Energy storage level in battery of house h in time step t; X^{(t,h)} — P2P electricity sale of house h in time step t; X^{p}(t,h\\rightarrow p) — P2P electricity sale of house h to peer p in time step t."},{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-9788b5496d-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"nt setups: decentralised (a) versus centralised battery (b). of market and steers its actions [39]. ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Fig. 2 shows the setups underlying the two distinct market designs. The Flexi User is designed for a setting with individual batteries at consumer level. Then, the structure in the Pool Hub considers a large battery at the community level. For both designs, we allow the trade of locally generated electricity within the community, where trade is the ability to sell excess electricity from renewable energy sources to peers. Each of the two setups gives the storage entity a certain role leading to the following distinct market design definitions:","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"Fig. 2 shows the setups underlying the two distinct market designs. The Flexi User is designed for a setting with individual batteries at consumer level. Then, the structure in the Pool Hub considers a large battery at the community level. For both designs, we allow the trade of locally generated electricity within the community, where trade is the ability to sell excess electricity from renewable energy sources to peers. Each of the two setups gives the storage entity a certain role leading to the following distinct market design definitions:"},{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-9788b5496d-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the co","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)"},{"evidence_id":"v141-b-g01-e15","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h \\in H is defined as the sum of all electricity flows X^{p}(t,h\\rightarrow p) from this house h \\in H to its peers p \\in H, Eq. (2). X^{(t,h)} = \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p) (2).","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h \\in H is defined as the sum of all electricity flows X^{p}(t,h\\rightarrow p) from this house h \\in H to its peers p \\in H, Eq. (2). X^{(t,h)} = \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p) (2)."},{"evidence_id":"v141-b-g01-e16","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Given that I^{p}(t,h\\leftarrow p) = \\psi^{P2P} \\cdot X^{p}(t,p\\rightarrow h) \\; \\forall p \\ne h, (3) the change of the flow direction indicates a purchase I^{p}(t,h\\leftarrow p) of one house h \\in H from its peer p \\in H.","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"Given that I^{p}(t,h\\leftarrow p) = \\psi^{P2P} \\cdot X^{p}(t,p\\rightarrow h) \\; \\forall p \\ne h, (3) the change of the flow direction indicates a purchase I^{p}(t,h\\leftarrow p) of one house h \\in H from its peer p \\in H."},{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p) (4).","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p) (4)."},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-9788b5496d-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Model formulation","anchor_text":"have the supply greater equal to demand by Eq. (1)4: 0 RES + Grid+ Battery discharge+ ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"All equations hold true for all h \\in H, t \\in T.","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"All equations hold true for all h \\in H, t \\in T."},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h∈H is defined as the sum of all electricity flows X_p^{(t,h\\rightarrow p)} from this house h∈H to its peers p∈H, Eq. (2). X^{(t,h)} = \\sum_{p \\neq h} X_p^{(t,h\\rightarrow p)} (2). Given that I_p^{(t,h\\leftarrow p)} = \\psi^{P2P} \\cdot X_p^{(t,p\\rightarrow h)} \\quad \\forall p \\neq h, (3), the change of the flow direction indicates a purchase I_p^{(t,h\\leftarrow p)} of one house h∈H from its peer p∈H. The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\neq h} I_p^{(t,h\\leftarrow p)} (4). As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\quad \\forall t \\in T. (5)","paper":"26-battery_flexibility","rule_id":"v141-c-R002","quote":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h∈H is defined as the sum of all electricity flows X_p^{(t,h\\rightarrow p)} from this house h∈H to its peers p∈H, Eq. (2). X^{(t,h)} = \\sum_{p \\neq h} X_p^{(t,h\\rightarrow p)} (2). Given that I_p^{(t,h\\leftarrow p)} = \\psi^{P2P} \\cdot X_p^{(t,p\\rightarrow h)} \\quad \\forall p \\neq h, (3), the change of the flow direction indicates a purchase I_p^{(t,h\\leftarrow p)} of one house h∈H from its peer p∈H. The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\neq h} I_p^{(t,h\\leftarrow p)} (4). As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\quad \\forall t \\in T. (5)"},{"evidence_id":"v141-b-g01-e19","location":{"location_id":"src-9788b5496d-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.2 Market specific constraints","anchor_text":"u- amount someone pays and the other one earns will cancel out, we leave ir these terms out of the o","equation_id":"(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In the Flexi User market with decentralised storage, costs arise when a prosumer consumes from the grid or buys from a fellow peer. However, in the P2P trade, the selling peer earns money and thereby reduces the costs of electricity for the overall community. As the amount someone pays and the other one earns will cancel out, we leave these terms out of the optimisation. Thus, the objective function for this case minimises the sum of costs for grid consumption G^{(t,h)}, Eq. (6). \\min \\sum_h \\sum_t [p_G^{(t)} \\cdot G^{(t,h)}] (6).","paper":"26-battery_flexibility","rule_id":"v141-c-R007","quote":"In the Flexi User market with decentralised storage, costs arise when a prosumer consumes from the grid or buys from a fellow peer. However, in the P2P trade, the selling peer earns money and thereby reduces the costs of electricity for the overall community. As the amount someone pays and the other one earns will cancel out, we leave these terms out of the optimisation. Thus, the objective function for this case minimises the sum of costs for grid consumption G^{(t,h)}, Eq. (6). \\min \\sum_h \\sum_t [p_G^{(t)} \\cdot G^{(t,h)}] (6)."}],"candidate_only":true,"classification_subtypes":["bilateral_trade_flow_feasibility"],"projection_statuses":["composite"],"taxonomy":{"primary_family":"kind-L5-222dcdefdb","secondary_families":[],"stage":"L5","ontological_kind":"bilateral_trade_flow_feasibility"},"semantic_definition":{},"source_units":[{"unit_id":"26-battery_flexibility::v141-a-M01::execution.energy_trade","paper_id":"26-battery_flexibility","mechanism_id":"v141-a-M01","function":"execution.energy_trade","source_occurrences":[{"id":"26-battery_flexibility::v141-c-R002::V::execution.energy_trade","rule_id":"v141-c-R002","market_meaning":"The dynamic local P2P price is applied as each house's purchase price for P2P exchanges. Scope: Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. Peers may sell excess electricity from locally generated renewable energy to other peers within the community. Scope: Flexi User peer exchanges within the community. P2P sales and purchases remain within the community under the design's exclusion of grid feed-in. Scope: Flexi User P2P sales and purchases. Each house's total P2P sales and purchases aggregate bilateral flows with other peers. Bilateral purchases equal the corresponding reverse-direction sales adjusted by the distribution-loss and DG-conversion factor; total community purchases must likewise equal adjusted community sales. Scope: Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. | Flexi User P2P sales and purchases. | Flexi User peer exchanges within the community. | Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e18","v141-b-g02-e16"]},"constraint_refs":["26-battery_flexibility::v141-c-R002::v141-c-R002-C001","26-battery_flexibility::v141-c-R002::v141-c-R002-C002","26-battery_flexibility::v141-c-R002::v141-c-R002-C003","26-battery_flexibility::v141-c-R002::v141-c-R002-C004"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"f5f3489e0aeb1a9f8ab702d6f918da1e040043dfec31bf1372cea634f8ce8089"},{"id":"26-battery_flexibility::v141-c-R007::V::execution.energy_trade","rule_id":"v141-c-R007","market_meaning":"The purchasing prosumer incurs a cost and the selling peer earns money when the P2P transaction occurs. Scope: Flexi User community P2P purchases by prosumers and corresponding seller receipts. Condition: A prosumer buys electricity from a fellow peer.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Flexi User community P2P purchases by prosumers and corresponding seller receipts.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e19"]},"constraint_refs":["26-battery_flexibility::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"b47cf85a1db97d6ba071d95e51f754d7c00025391b4f040009b2cde76846e99d"}],"constraints":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The dynamic local P2P price is applied as each house's purchase price for P2P exchanges. Scope: Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":["v141-c-R002-P001"],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e16","v141-b-g01-e06"],"ref":"26-battery_flexibility::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e01","location":{"location_id":"src-9788b5496d-p04-c2r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"he ability to sell excess electricity from renewable energy sources to peers. Each of the two setups","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Decentralised storage – Flexi User Market: This market design applies rules to the system setup with individually owned batteries. Prosumers and consumers within a community can trade locally produced energy at a dynamic local P2P price. Privately owned storage can be charged by DG from prosumers within the community."},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-9788b5496d-p07-c1r3__v141-a-M01-pricing","page":7,"printed_page":null,"section":"4.1.4 Electricity prices","anchor_text":"Fig. 3. Demand cover for exemplary houses on a scaled up to represent typical price levels customers","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"A reasonable price for P2P trade should reflect the willingness of each prosumer to pay for an extra unit of electricity under the assumption that there is no possibility for local trade or storage. The shadow price of each single prosumer can be seen as the willingness to pay of each prosumer. This approach is analogous to the proposition of Abbaspourtorbati et al. [45] who calculated clearing prices by the dual variables of the energy balance equations. To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step. Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."},{"evidence_id":"v141-b-g01-e06","location":{"location_id":"src-9788b5496d-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"Table 1","anchor_text":"dem(t , h ) Demand of house h in time step t res (t , h ) Renewable energy production of house h in ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Table 1. Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T — Hours t in time horizon T; h, p ∈ H — Houses h and peers p in community H. Scalars: \\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale; \\underline{s}/\\bar{s} — Upper/lower bounds of storage level in battery; \\alpha/\\beta — Maximum charge/discharge rate of battery; \\eta^c/\\eta^d — Battery charging/discharging efficiency. Parameters: dem^{(t,h)} — Demand of house h in time step t; res^{(t,h)} — Renewable energy production of house h in time step t; p_G^{(t)} — Price of electricity from the grid in time step t; p_{p2p}^{(t,h)} — Price of electricity in the local market for house h in time step t; p_C^{(t)} — Price of charging the common battery in time step t; p_D^{(t,h)} — Price of discharging the common battery in time step t. Variables: C^{(t,h)} — Charge of battery of house h in time step t; D^{(t,h)} — Discharge of battery of house h in time step t; G^{(t,h)} — Grid consumption of house h in time step t; I^{(t,h)} — P2P electricity purchase of house h in time step t; I^{p}(t,h\\leftarrow p) — P2P electricity purchase of house h from peer p in time step t; S^{(t,h)} — Energy storage level in battery of house h in time step t; X^{(t,h)} — P2P electricity sale of house h in time step t; X^{p}(t,h\\rightarrow p) — P2P electricity sale of house h to peer p in time step t."}]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"core","statement":"Peers may sell excess electricity from locally generated renewable energy to other peers within the community. Scope: Flexi User peer exchanges within the community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"],"ref":"26-battery_flexibility::v141-c-R002::v141-c-R002-C002","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-9788b5496d-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"nt setups: decentralised (a) versus centralised battery (b). of market and steers its actions [39]. ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Fig. 2 shows the setups underlying the two distinct market designs. The Flexi User is designed for a setting with individual batteries at consumer level. Then, the structure in the Pool Hub considers a large battery at the community level. For both designs, we allow the trade of locally generated electricity within the community, where trade is the ability to sell excess electricity from renewable energy sources to peers. Each of the two setups gives the storage entity a certain role leading to the following distinct market design definitions:"}]},{"constraint_id":"v141-c-R002-C003","kind":"procedural","role":"core","statement":"P2P sales and purchases remain within the community under the design's exclusion of grid feed-in. Scope: Flexi User P2P sales and purchases.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e18"],"ref":"26-battery_flexibility::v141-c-R002::v141-c-R002-C003","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-9788b5496d-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the co","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)"}]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"core","statement":"Each house's total P2P sales and purchases aggregate bilateral flows with other peers. Bilateral purchases equal the corresponding reverse-direction sales adjusted by the distribution-loss and DG-conversion factor; total community purchases must likewise equal adjusted community sales. Scope: Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","expression":"\\begin{aligned} X^{(t,h)} &= \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p), && \\forall t\\in T,\\, h\\in H; \\\\ I^{p}(t,h\\leftarrow p) &= \\psi^{P2P}\\cdot X^{p}(t,p\\rightarrow h), && \\forall t\\in T,\\, h,p\\in H,\\, p\\ne h; \\\\ I^{(t,h)} &= \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p), && \\forall t\\in T,\\, h\\in H; \\\\ \\sum_h \\psi^{P2P}\\cdot X^{(t,h)} &= \\sum_h I^{(t,h)}, && \\forall t\\in T. \\end{aligned}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R002-X001","v141-c-R002-X002","v141-c-R002-X003","v141-c-R002-X004"],"parameter_refs":["v141-c-R002-P002"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e18","v141-b-g01-e14","v141-b-g02-e10"],"ref":"26-battery_flexibility::v141-c-R002::v141-c-R002-C004","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e06","location":{"location_id":"src-9788b5496d-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"Table 1","anchor_text":"dem(t , h ) Demand of house h in time step t res (t , h ) Renewable energy production of house h in ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Table 1. Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T — Hours t in time horizon T; h, p ∈ H — Houses h and peers p in community H. Scalars: \\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale; \\underline{s}/\\bar{s} — Upper/lower bounds of storage level in battery; \\alpha/\\beta — Maximum charge/discharge rate of battery; \\eta^c/\\eta^d — Battery charging/discharging efficiency. Parameters: dem^{(t,h)} — Demand of house h in time step t; res^{(t,h)} — Renewable energy production of house h in time step t; p_G^{(t)} — Price of electricity from the grid in time step t; p_{p2p}^{(t,h)} — Price of electricity in the local market for house h in time step t; p_C^{(t)} — Price of charging the common battery in time step t; p_D^{(t,h)} — Price of discharging the common battery in time step t. Variables: C^{(t,h)} — Charge of battery of house h in time step t; D^{(t,h)} — Discharge of battery of house h in time step t; G^{(t,h)} — Grid consumption of house h in time step t; I^{(t,h)} — P2P electricity purchase of house h in time step t; I^{p}(t,h\\leftarrow p) — P2P electricity purchase of house h from peer p in time step t; S^{(t,h)} — Energy storage level in battery of house h in time step t; X^{(t,h)} — P2P electricity sale of house h in time step t; X^{p}(t,h\\rightarrow p) — P2P electricity sale of house h to peer p in time step t."},{"evidence_id":"v141-b-g01-e15","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h \\in H is defined as the sum of all electricity flows X^{p}(t,h\\rightarrow p) from this house h \\in H to its peers p \\in H, Eq. (2). X^{(t,h)} = \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p) (2)."},{"evidence_id":"v141-b-g01-e16","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Given that I^{p}(t,h\\leftarrow p) = \\psi^{P2P} \\cdot X^{p}(t,p\\rightarrow h) \\; \\forall p \\ne h, (3) the change of the flow direction indicates a purchase I^{p}(t,h\\leftarrow p) of one house h \\in H from its peer p \\in H."},{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p) (4)."},{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-9788b5496d-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the co","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)"},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-9788b5496d-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Model formulation","anchor_text":"have the supply greater equal to demand by Eq. (1)4: 0 RES + Grid+ Battery discharge+ ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"All equations hold true for all h \\in H, t \\in T."},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h∈H is defined as the sum of all electricity flows X_p^{(t,h\\rightarrow p)} from this house h∈H to its peers p∈H, Eq. (2). X^{(t,h)} = \\sum_{p \\neq h} X_p^{(t,h\\rightarrow p)} (2). Given that I_p^{(t,h\\leftarrow p)} = \\psi^{P2P} \\cdot X_p^{(t,p\\rightarrow h)} \\quad \\forall p \\neq h, (3), the change of the flow direction indicates a purchase I_p^{(t,h\\leftarrow p)} of one house h∈H from its peer p∈H. The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\neq h} I_p^{(t,h\\leftarrow p)} (4). As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\quad \\forall t \\in T. (5)"}]},{"constraint_id":"v141-c-R007-C001","kind":"logical","role":"core","statement":"The purchasing prosumer incurs a cost and the selling peer earns money when the P2P transaction occurs. Scope: Flexi User community P2P purchases by prosumers and corresponding seller receipts. Condition: A prosumer buys electricity from a fellow peer.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e19"],"ref":"26-battery_flexibility::v141-c-R007::v141-c-R007-C001","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-e19","location":{"location_id":"src-9788b5496d-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.2 Market specific constraints","anchor_text":"u- amount someone pays and the other one earns will cancel out, we leave ir these terms out of the o","equation_id":"(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In the Flexi User market with decentralised storage, costs arise when a prosumer consumes from the grid or buys from a fellow peer. However, in the P2P trade, the selling peer earns money and thereby reduces the costs of electricity for the overall community. As the amount someone pays and the other one earns will cancel out, we leave these terms out of the optimisation. Thus, the objective function for this case minimises the sum of costs for grid consumption G^{(t,h)}, Eq. (6). \\min \\sum_h \\sum_t [p_G^{(t)} \\cdot G^{(t,h)}] (6)."}]}],"variables":[{"variable_id":"v141-c-R002-X001","symbol":"X^{(t,h)}","meaning":"P2P electricity sale of house h in time step t, aggregated over peers p != h.","kind":"operational","domain":"Unspecified energy quantity indexed by t in T and h in H; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::x::v141-c-R002-X001"},{"variable_id":"v141-c-R002-X002","symbol":"X^{p}(t,h\\rightarrow p)","meaning":"P2P electricity sale of house h to peer p in time step t.","kind":"operational","domain":"Unspecified energy flow indexed by t in T and h,p in H with p != h in Eqs. (2)-(3); the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h","p"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::x::v141-c-R002-X002"},{"variable_id":"v141-c-R002-X003","symbol":"I^{(t,h)}","meaning":"P2P electricity purchase of house h in time step t, aggregated over peers p != h.","kind":"operational","domain":"Unspecified energy quantity indexed by t in T and h in H; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e17"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::x::v141-c-R002-X003"},{"variable_id":"v141-c-R002-X004","symbol":"I^{p}(t,h\\leftarrow p)","meaning":"P2P electricity purchase of house h from peer p in time step t.","kind":"operational","domain":"Unspecified energy flow indexed by t in T and h,p in H with p != h; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h","p"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e16","v141-b-g01-e17"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::x::v141-c-R002-X004"}],"parameters":[{"parameter_id":"v141-c-R002-P001","symbol":"p_{p2p}^{(t,h)}","meaning":"Price of electricity in the local market for house h in time step t; the dynamic local P2P purchase price applied to house h's P2P exchanges.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e01","v141-b-g02-e16"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::theta::v141-c-R002-P001"},{"parameter_id":"v141-c-R002-P002","symbol":"\\psi^{P2P}","meaning":"Distribution network losses and conversion of DG for P2P sale; the multiplicative factor relating a peer sale flow to the corresponding purchase flow.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e16","v141-b-g01-e18"],"source_rule_id":"v141-c-R002","declaration_ref":"26-battery_flexibility::v141-c-R002::theta::v141-c-R002-P002"}]}],"source_definitions":[{"unit_id":"26-battery_flexibility::v141-a-M01::execution.energy_trade","stage":"L5","subtype":"bilateral_trade_flow_feasibility","projection_status":"composite","target_definition":"The primary definition is the feasible relationship for bilaterally transacted electricity quantities: each household's total sales and total purchases respectively aggregate the pairwise flows, I^{p}(t,h←p)=ψ^{P2P}X^{p}(t,p→h), and total sales after community-loss adjustment equal total purchases; it also contains an execution rule that applies each household's dynamic purchase price to P2P exchange.","form_kind":"mathematical","identity_fields":["Object: directed bilateral buy and sell electricity quantities within the community, and the application of the transaction purchase price","Core relationship 1: aggregation of pairwise flows, loss conversion between the reverse buy and sell directions, and consistency of community totals","Core relationship 2: the dynamic local purchase price is applied to the P2P exchange of the corresponding house","Output: the feasible traded-electricity-quantity relationship and the price-application relationship"],"variation_fields":["The house and the peer must be different, indexed by the model time period","ψ^{P2P} denotes distribution losses and distributed-generation conversion","Transactions are limited to within the community; grid feed-in is not allowed","Selling local renewable surplus electricity to peers is allowed"],"constraint_refs":["26-battery_flexibility::v141-c-R002::v141-c-R002-C001","26-battery_flexibility::v141-c-R002::v141-c-R002-C002","26-battery_flexibility::v141-c-R002::v141-c-R002-C003","26-battery_flexibility::v141-c-R002::v141-c-R002-C004","26-battery_flexibility::v141-c-R007::v141-c-R007-C001"],"paper_id":"26-battery_flexibility","mechanism_id":"v141-a-M01","function":"execution.energy_trade","template_code":"BCT"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/173"});
